// HRMS shared types and helpers (Phase 1).
//
// The Phase 1 tables are not in src/integrations/supabase/types.ts — that file is
// generated by `supabase gen types`, which needs project credentials. So the row
// shapes are declared here by hand and queries go through `hrmsDb()`, mirroring
// how email_log is already accessed elsewhere in the app. Once the types are
// regenerated these interfaces can be swapped for Tables<"employees"> etc.

import { supabase } from "@/integrations/supabase/client";

/**
 * Supabase client cast to `any` for HRMS tables only.
 *
 * Narrow escape hatch, deliberately named so it is obvious at every call site
 * that these queries are unchecked against the generated schema — the row types
 * below are the contract instead.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const hrmsDb = () => supabase as any;

