export const statusMeta = (id: string) =>
  EMPLOYMENT_STATUSES.find((s) => s.id === id) ?? EMPLOYMENT_STATUSES[0];

/** "510" minutes -> "8h 30m". Used wherever a duration is displayed. */
export function formatMinutes(mins: number): string {
  const m = Math.max(0, Math.round(mins));
  const h = Math.floor(m / 60);
  const rest = m % 60;
  if (h === 0) return `${rest}m`;
  return rest === 0 ? `${h}h` : `${h}h ${rest}m`;
}

/**
 * Clock time at which an arrival becomes "late" — work start plus the grace
 * period. Pure so Phase 2's late calculation can be tested without a database.
 */
export function lateAfter(workStart: string, graceMinutes: number): string {
  const [hh, mm] = workStart.split(":").map((v) => Number(v) || 0);
  const total = hh * 60 + mm + (Number(graceMinutes) || 0);
  const h = Math.floor((total % 1440) / 60);
  const m = total % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

